#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    /* ----- error handling ----- */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);

    /* parsing failed (no digits) */
    if (endptr == argv[1]) {
        puts("BAD_INPUT");
        return 0;
    }

    /* negative number */
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }

    /* zero rows */
    if (n == 0) {
        puts("EMPTY");
        return 0;
    }

    /* limit imposed by the original program (array size 61) */
    if (n > 60) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ----- Pascal's triangle ----- */
    long long row[61] = {0};

    for (int r = 0; r < n; ++r) {
        /* compute the r‑th row (0‑based) */
        row[r] = 1;                     /* last element is always 1 */
        for (int c = r - 1; c > 0; --c) /* fill the interior, backwards */
            row[c] = row[c] + row[c - 1];
        row[0] = 1;                     /* first element is always 1 */

        /* ----- output the row ----- */
        for (int c = 0; c <= r; ++c) {
            if (c > 0)                  /* space before every element except the first */
                putchar(' ');
            printf("%lld", row[c]);
        }
        putchar('\n');
    }

    return 0;
}
